 21→// openRepository opens the git repository with linked worktree support enabled.
 22→// This is a convenience wrapper around strategy.OpenRepository() for use in the CLI package.
 23→func openRepository(ctx context.Context) (*git.Repository, error) {
 24→	repo, err := strategy.OpenRepository(ctx)
 25→	if err != nil {
 26→		return nil, fmt.Errorf("failed to open repository: %w", err)
 27→	}
 28→	return repo, nil
 29→}
