 31→// GitAuthor represents the git user configuration
 32→type GitAuthor struct {
 33→	Name  string
 34→	Email string
 35→}
 36→
 37→// GetGitAuthor retrieves the git user.name and user.email from the repository config.
 38→// It checks local config first, then falls back to global config.
 39→// If go-git can't find the config, it falls back to using the git command.
 40→// Returns fallback defaults if no user is configured anywhere.
 41→func GetGitAuthor(ctx context.Context) (*GitAuthor, error) {
 42→	repo, err := openRepository(ctx)
 43→	if err != nil {
 44→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 45→	}
 46→
 47→	name, email := strategy.GetGitAuthorFromRepo(repo)
 48→
 49→	// If go-git returned defaults, try using git command as fallback
 50→	// This handles cases where go-git can't find the config (e.g., different HOME paths,
 51→	// non-standard config locations, or environment issues in hook contexts)
 52→	if name == "Unknown" {
 53→		if gitName := getGitConfigValue(ctx, "user.name"); gitName != "" {
 54→			name = gitName
 55→		}
 56→	}
 57→	if email == "unknown@local" {
 58→		if gitEmail := getGitConfigValue(ctx, "user.email"); gitEmail != "" {
 59→			email = gitEmail
 60→		}
 61→	}
 62→
 63→	return &GitAuthor{
 64→		Name:  name,
 65→		Email: email,
 66→	}, nil
 67→}
