 69→// getGitConfigValue retrieves a git config value using the git command.
 70→// Returns empty string if the value is not set or on error.
 71→func getGitConfigValue(ctx context.Context, key string) string {
 72→	cmd := exec.CommandContext(ctx, "git", "config", "--get", key)
 73→	output, err := cmd.Output()
 74→	if err != nil {
 75→		return ""
 76→	}
 77→	return strings.TrimSpace(string(output))
 78→}
