 80→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 81→// It determines the default branch by:
 82→// 1. Checking the remote origin's HEAD reference
 83→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 84→// Returns (isDefault, branchName, error)
 85→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 86→	repo, err := openRepository(ctx)
 87→	if err != nil {
 88→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 89→	}
 90→
 91→	// Get current branch
 92→	head, err := repo.Head()
 93→	if err != nil {
 94→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 95→	}
 96→
 97→	if !head.Name().IsBranch() {
 98→		// Detached HEAD - not on any branch
 99→		return false, "", nil
100→	}
101→
102→	currentBranch := head.Name().Short()
103→
104→	// Try to get default branch from remote origin's HEAD
105→	defaultBranch := getDefaultBranchFromRemote(repo)
106→
107→	// If we couldn't determine from remote, use common defaults
108→	if defaultBranch == "" {
109→		// Check if current branch is a common default name
110→		if currentBranch == "main" || currentBranch == "master" {
111→			return true, currentBranch, nil
112→		}
113→		return false, currentBranch, nil
114→	}
115→
116→	return currentBranch == defaultBranch, currentBranch, nil
117→}
