119→// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
120→// Returns empty string if unable to determine.
121→func getDefaultBranchFromRemote(repo *git.Repository) string {
122→	// Try to get the symbolic reference for origin/HEAD
123→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
124→	if err == nil && ref != nil {
125→		// ref.Target() gives us something like "refs/remotes/origin/main"
126→		target := ref.Target().String()
127→		if strings.HasPrefix(target, "refs/remotes/origin/") {
128→			return strings.TrimPrefix(target, "refs/remotes/origin/")
129→		}
130→	}
131→
132→	// Fallback: check if origin/main or origin/master exists
133→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
134→		return "main"
135→	}
136→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
137→		return "master"
138→	}
139→
140→	return ""
141→}
