143→// ShouldSkipOnDefaultBranch checks if we're on the default branch.
144→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
145→// skip the operation to avoid polluting main/master history.
146→// If the branch cannot be determined, returns (false, "") to allow the operation.
147→func ShouldSkipOnDefaultBranch(ctx context.Context) (bool, string) {
148→	isDefault, branchName, err := IsOnDefaultBranch(ctx)
149→	if err != nil {
150→		// If we can't determine, allow the operation
151→		return false, ""
152→	}
153→	return isDefault, branchName
154→}
