156→// GetCurrentBranch returns the name of the current branch.
157→// Returns an error if in detached HEAD state or if not in a git repository.
158→func GetCurrentBranch(ctx context.Context) (string, error) {
159→	repo, err := openRepository(ctx)
160→	if err != nil {
161→		return "", fmt.Errorf("failed to open git repository: %w", err)
162→	}
163→
164→	head, err := repo.Head()
165→	if err != nil {
166→		return "", fmt.Errorf("failed to get HEAD: %w", err)
167→	}
168→
169→	if !head.Name().IsBranch() {
170→		return "", errors.New("not on a branch (detached HEAD)")
171→	}
172→
173→	return head.Name().Short(), nil
174→}
