176→// GetMergeBase finds the common ancestor (merge-base) between two branches.
177→// Returns the hash of the merge-base commit.
178→func GetMergeBase(ctx context.Context, branch1, branch2 string) (*plumbing.Hash, error) {
179→	repo, err := openRepository(ctx)
180→	if err != nil {
181→		return nil, fmt.Errorf("failed to open git repository: %w", err)
182→	}
183→
184→	// Resolve branch references
185→	ref1, err := repo.Reference(plumbing.NewBranchReferenceName(branch1), true)
186→	if err != nil {
187→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
188→	}
189→
190→	ref2, err := repo.Reference(plumbing.NewBranchReferenceName(branch2), true)
191→	if err != nil {
192→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
193→	}
194→
195→	// Get commit objects
196→	commit1, err := repo.CommitObject(ref1.Hash())
197→	if err != nil {
198→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
199→	}
200→
201→	commit2, err := repo.CommitObject(ref2.Hash())
202→	if err != nil {
203→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
204→	}
205→
206→	// Find common ancestor
207→	mergeBase, err := commit1.MergeBase(commit2)
208→	if err != nil {
209→		return nil, fmt.Errorf("failed to find merge base: %w", err)
210→	}
211→
212→	if len(mergeBase) == 0 {
213→		return nil, errors.New("no common ancestor found")
214→	}
215→
216→	hash := mergeBase[0].Hash
217→	return &hash, nil
218→}
