220→// HasUncommittedChanges checks if there are any uncommitted changes in the repository.
221→// This includes staged changes, unstaged changes, and untracked files.
222→// Uses git CLI instead of go-git because go-git doesn't respect global gitignore
223→// (core.excludesfile) which can cause false positives for globally ignored files.
224→func HasUncommittedChanges(ctx context.Context) (bool, error) {
225→	cmd := exec.CommandContext(ctx, "git", "status", "--porcelain")
226→	output, err := cmd.Output()
227→	if err != nil {
228→		return false, fmt.Errorf("failed to get git status: %w", err)
229→	}
230→
231→	// If output is empty, there are no changes
232→	return len(strings.TrimSpace(string(output))) > 0, nil
233→}
