235→// findNewUntrackedFiles finds files that are newly untracked (not in pre-existing list)
236→func findNewUntrackedFiles(current, preExisting []string) []string {
237→	preExistingSet := make(map[string]bool)
238→	for _, file := range preExisting {
239→		preExistingSet[file] = true
240→	}
241→
242→	var newFiles []string
243→	for _, file := range current {
244→		if !preExistingSet[file] {
245→			newFiles = append(newFiles, file)
246→		}
247→	}
248→	return newFiles
249→}
