251→// BranchExistsOnRemote checks if a branch exists on the origin remote.
252→// First checks local remote-tracking refs, then queries the actual remote
253→// via git ls-remote in case local refs are stale (e.g., after a fresh clone
254→// that didn't fetch all branches).
255→func BranchExistsOnRemote(ctx context.Context, branchName string) (bool, error) {
256→	repo, err := openRepository(ctx)
257→	if err != nil {
258→		return false, fmt.Errorf("failed to open git repository: %w", err)
259→	}
260→
261→	// Check for remote reference: refs/remotes/origin/<branchName>
262→	_, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
263→	if err == nil {
264→		return true, nil
265→	}
266→	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
267→		return false, fmt.Errorf("failed to check remote branch: %w", err)
268→	}
269→
270→	// Local remote-tracking ref not found — query the actual remote.
271→	lsCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
272→	defer cancel()
273→
274→	lsCmd := exec.CommandContext(lsCtx, "git", "ls-remote", "--heads", "origin", "refs/heads/"+branchName)
275→	output, lsErr := lsCmd.Output()
276→	if lsErr != nil {
277→		// ls-remote failed (no network, no remote, etc.) — treat as not found
278→		return false, nil
279→	}
280→
281→	return len(bytes.TrimSpace(output)) > 0, nil
282→}
