302→// CheckoutBranch switches to the specified local branch or commit.
303→// Uses git CLI instead of go-git to work around go-git v5 bug where Checkout
304→// deletes untracked files (see https://github.com/go-git/go-git/issues/970).
305→// Should be switched back to go-git once we upgrade to go-git v6
306→// Returns an error if the ref doesn't exist or checkout fails.
307→func CheckoutBranch(ctx context.Context, ref string) error {
308→	if strings.HasPrefix(ref, "-") {
309→		return fmt.Errorf("checkout failed: invalid ref %q", ref)
310→	}
311→	cmd := exec.CommandContext(ctx, "git", "checkout", ref)
312→	if output, err := cmd.CombinedOutput(); err != nil {
313→		return fmt.Errorf("checkout failed: %s: %w", strings.TrimSpace(string(output)), err)
314→	}
315→	return nil
316→}
