318→// ValidateBranchName checks if a branch name is valid using git check-ref-format.
319→// Returns an error if the name is invalid or contains unsafe characters.
320→func ValidateBranchName(ctx context.Context, branchName string) error {
321→	cmd := exec.CommandContext(ctx, "git", "check-ref-format", "--branch", branchName)
322→	if err := cmd.Run(); err != nil {
323→		return fmt.Errorf("invalid branch name %q", branchName)
