328→// FetchAndCheckoutRemoteBranch fetches a branch from origin and creates a local tracking branch.
329→// Uses git CLI instead of go-git for fetch because go-git doesn't use credential helpers,
330→// which breaks HTTPS URLs that require authentication.
331→func FetchAndCheckoutRemoteBranch(ctx context.Context, branchName string) error {
332→	// Validate branch name before using in shell command (branchName comes from user CLI input)
333→	if err := ValidateBranchName(ctx, branchName); err != nil {
334→		return err
335→	}
336→
337→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
338→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
339→	defer cancel()
340→
341→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
342→
343→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
344→	if output, err := fetchCmd.CombinedOutput(); err != nil {
345→		if ctx.Err() == context.DeadlineExceeded {
346→			return errors.New("fetch timed out after 2 minutes")
347→		}
348→		return fmt.Errorf("failed to fetch branch from origin: %s: %w", strings.TrimSpace(string(output)), err)
349→	}
350→
351→	repo, err := openRepository(ctx)
352→	if err != nil {
353→		return fmt.Errorf("failed to open repository: %w", err)
354→	}
355→
356→	// Get the remote branch reference
357→	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
358→	if err != nil {
359→		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
360→	}
361→
362→	// Create local branch pointing to the same commit
363→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
364→	err = repo.Storer.SetReference(localRef)
365→	if err != nil {
366→		return fmt.Errorf("failed to create local branch: %w", err)
367→	}
368→
369→	// Checkout the new local branch
370→	return CheckoutBranch(ctx, branchName)
371→}
