430→		if ctx.Err() == context.DeadlineExceeded {
431→			return errors.New("treeless fetch timed out after 2 minutes")
432→		}
433→		return fmt.Errorf("failed to treeless-fetch %s from origin: %s: %w", branchName, strings.TrimSpace(string(output)), err)
