// TestCheckpointToken_HTTPServer_SendsAuthHeader uses a real HTTP server to verify
// that the bearer token is actually sent as an HTTP header in git fetch requests.
// Not parallel: uses t.Chdir()
func TestCheckpointToken_HTTPServer_SendsAuthHeader(t *testing.T) {
	t.Setenv(CheckpointTokenEnvVar, "test-bearer-token-abc123")

	var (
		mu            sync.Mutex
		capturedAuth  string
		requestCount  int
	)

	// Start an HTTP server that captures the Authorization header
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		capturedAuth = r.Header.Get("Authorization")
		requestCount++
		mu.Unlock()

		// Return a minimal git error response — we only care about the header
		w.WriteHeader(http.StatusForbidden)
		fmt.Fprintln(w, "forbidden")
	}))
	defer srv.Close()

	// Set up a local git repo so the git command can run
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	// The target URL is the test server — it's HTTPS-like (http://) but parseGitRemoteURL
	// will parse it. We need to use it as a direct URL target.
	// git fetch to our test server. It will fail (403) but we'll capture the header.
	target := srv.URL + "/org/repo.git"

	cmd := CheckpointGitCommand(context.Background(), target,
		"fetch", target, "+refs/heads/main:refs/remotes/origin/main")
	cmd.Dir = tmpDir
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")

	// We expect this to fail (the server returns 403), but the header should be sent
	_ = cmd.Run()

	mu.Lock()
	defer mu.Unlock()

	require.Greater(t, requestCount, 0, "server should have received at least one request")
	assert.Equal(t, "Bearer test-bearer-token-abc123", capturedAuth,
		"git should send the bearer token as an Authorization header")
}

